from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    if old not in text:
        raise SystemExit(f"anchor not found in {path}: {old[:120]!r}")
    file.write_text(text.replace(old, new, 1))


# Core contract: membership-gated reads are one storage operation/snapshot.
replace_once(
    "crates/ucr-core/src/group.rs",
    '''    /// Applies one idempotent security-sensitive Group change with optimistic revision checking.\n''',
    '''    /// Atomically verifies the subject is an active Group member and loads one membership from the same storage snapshot.\n    ///\n    /// Inactive/missing callers return non-disclosing absence rather than allowing Core to compose a racy pre-check plus read.\n    ///\n    /// # Errors\n    /// Rejects scope mismatches and returns explicit durable-store failures.\n    fn group_membership_for_active_member(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        member: &ucr_model::PrincipalRef,\n    ) -> Result<Option<GroupMembership>, DurableStoreError>;\n\n    /// Atomically verifies the subject is an active Group member and loads the bounded membership set from the same storage snapshot.\n    ///\n    /// # Errors\n    /// Rejects scope mismatches, inactive callers, invalid bounds, and explicit durable-store failures.\n    fn group_memberships_for_active_member(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        max_items: usize,\n    ) -> Result<Vec<GroupMembership>, DurableStoreError>;\n\n    /// Applies one idempotent security-sensitive Group change with optimistic revision checking.\n'''
)

# Core façade must call the atomic storage operations instead of split pre-check/read calls.
old_runtime = '''    /// Reads one membership only for an authorized active Group member.\n    ///\n    /// # Errors\n    /// Returns authorization or durable-store failures; inactive callers cannot use membership lookup as an existence oracle.\n    pub fn group_membership(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        member: &ucr_model::PrincipalRef,\n    ) -> Result<Option<GroupMembership>, AuthorizedMutationError> {\n        self.require(subject, scope, GROUP_READ_PERMISSION)?;\n        let caller = self\n            .store\n            .group_membership(scope, group_id, &subject.principal)\n            .map_err(AuthorizedMutationError::Store)?;\n        if !caller.is_some_and(|value| value.state == GroupMemberState::Active) {\n            return Ok(None);\n        }\n        self.store\n            .group_membership(scope, group_id, member)\n            .map_err(AuthorizedMutationError::Store)\n    }\n\n    /// Reads one bounded canonical membership set for an authorized active Group member.\n    ///\n    /// # Errors\n    /// Returns authorization, membership, invalid-bound, or durable-store failures.\n    pub fn group_memberships(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        max_items: usize,\n    ) -> Result<Vec<GroupMembership>, AuthorizedMutationError> {\n        self.require(subject, scope, GROUP_READ_PERMISSION)?;\n        let caller = self\n            .store\n            .group_membership(scope, group_id, &subject.principal)\n            .map_err(AuthorizedMutationError::Store)?;\n        if !caller.is_some_and(|value| value.state == GroupMemberState::Active) {\n            return Err(AuthorizedMutationError::Store(\n                DurableStoreError::PermissionDenied,\n            ));\n        }\n        self.store\n            .group_memberships(scope, group_id, max_items)\n            .map_err(AuthorizedMutationError::Store)\n    }\n'''
new_runtime = '''    /// Reads one membership only for an authorized active Group member.\n    ///\n    /// # Errors\n    /// Returns authorization or durable-store failures; membership authorization and the target read share one storage snapshot.\n    pub fn group_membership(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        member: &ucr_model::PrincipalRef,\n    ) -> Result<Option<GroupMembership>, AuthorizedMutationError> {\n        self.require(subject, scope, GROUP_READ_PERMISSION)?;\n        self.store\n            .group_membership_for_active_member(subject, scope, group_id, member)\n            .map_err(AuthorizedMutationError::Store)\n    }\n\n    /// Reads one bounded canonical membership set for an authorized active Group member.\n    ///\n    /// # Errors\n    /// Returns authorization, membership, invalid-bound, or durable-store failures; membership authorization and the list read share one storage snapshot.\n    pub fn group_memberships(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        max_items: usize,\n    ) -> Result<Vec<GroupMembership>, AuthorizedMutationError> {\n        self.require(subject, scope, GROUP_READ_PERMISSION)?;\n        self.store\n            .group_memberships_for_active_member(subject, scope, group_id, max_items)\n            .map_err(AuthorizedMutationError::Store)\n    }\n'''
replace_once("crates/ucr-core/src/authorized_runtime.rs", old_runtime, new_runtime)

# Memory implementation: one lock spans active-caller check and returned read/list.
replace_once(
    "crates/ucr-storage-memory/src/group_store.rs",
    '''    fn apply_group_change(\n        &self,\n        actor: &ScopedPrincipal,\n        change: &GroupChange,\n    ) -> Result<DurableRecordStatus, DurableStoreError> {\n''',
    '''    fn group_membership_for_active_member(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        member: &PrincipalRef,\n    ) -> Result<Option<GroupMembership>, DurableStoreError> {\n        if subject.scope != *scope {\n            return Err(DurableStoreError::PermissionDenied);\n        }\n        let state = self.state.lock().map_err(|_| DurableStoreError::Internal)?;\n        let caller = state\n            .group_memberships\n            .get(&membership_key(scope, group_id, &subject.principal))\n            .filter(|membership| membership.member == subject.principal);\n        if !caller.is_some_and(|membership| membership.state == GroupMemberState::Active) {\n            return Ok(None);\n        }\n        Ok(state\n            .group_memberships\n            .get(&membership_key(scope, group_id, member))\n            .filter(|membership| membership.member == *member)\n            .cloned())\n    }\n\n    fn group_memberships_for_active_member(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        max_items: usize,\n    ) -> Result<Vec<GroupMembership>, DurableStoreError> {\n        if subject.scope != *scope {\n            return Err(DurableStoreError::PermissionDenied);\n        }\n        let state = self.state.lock().map_err(|_| DurableStoreError::Internal)?;\n        let caller = state\n            .group_memberships\n            .get(&membership_key(scope, group_id, &subject.principal))\n            .filter(|membership| membership.member == subject.principal);\n        if !caller.is_some_and(|membership| membership.state == GroupMemberState::Active) {\n            return Err(DurableStoreError::PermissionDenied);\n        }\n        validate_group_member_list_limit(max_items).map_err(map_group_error)?;\n        let group = state\n            .groups\n            .get(&group_key(scope, group_id))\n            .ok_or(DurableStoreError::InvalidRecord)?;\n        let mut memberships = state\n            .group_memberships\n            .values()\n            .filter(|membership| membership.scope == *scope && membership.group_id == *group_id)\n            .cloned()\n            .collect::<Vec<_>>();\n        memberships = canonical_group_memberships(group, &memberships).map_err(map_group_error)?;\n        if memberships.len() > max_items {\n            return Err(DurableStoreError::Full);\n        }\n        Ok(memberships)\n    }\n\n    fn apply_group_change(\n        &self,\n        actor: &ScopedPrincipal,\n        change: &GroupChange,\n    ) -> Result<DurableRecordStatus, DurableStoreError> {\n'''
)

memory_test = '''    #[test]\n    fn membership_gated_reads_fail_after_caller_removal() {\n        let store = MemoryLocalStore::default();\n        let owner = subject("snapshot-owner", PrincipalKind::Person);\n        let caller = subject("snapshot-caller", PrincipalKind::Person);\n        let target = subject("snapshot-target", PrincipalKind::Organization);\n        let (conversation, group) = group_fixture("snapshot-read", &owner);\n        store.create_group(&conversation, &group, &owner).expect("group");\n        for (revision, event_id, principal) in [\n            (0, "snapshot-add-caller", caller.principal.clone()),\n            (1, "snapshot-add-target", target.principal.clone()),\n        ] {\n            store\n                .apply_group_change(\n                    &owner,\n                    &GroupChange {\n                        event_id: EventId::from_opaque(oid(event_id)),\n                        scope: scope(),\n                        group_id: group.group_id.clone(),\n                        expected_revision: revision,\n                        kind: GroupChangeKind::AddMember {\n                            member: principal,\n                            role: GroupRole::Member,\n                        },\n                        next_crypto_state: None,\n                    },\n                )\n                .expect("add member");\n        }\n        assert_eq!(\n            store\n                .group_membership_for_active_member(\n                    &caller,\n                    &scope(),\n                    &group.group_id,\n                    &target.principal,\n                )\n                .expect("gated membership")\n                .map(|membership| membership.member),\n            Some(target.principal.clone())\n        );\n        assert!(\n            store\n                .group_memberships_for_active_member(&caller, &scope(), &group.group_id, 16)\n                .expect("gated memberships")\n                .iter()\n                .any(|membership| membership.member == target.principal)\n        );\n        store\n            .apply_group_change(\n                &owner,\n                &GroupChange {\n                    event_id: EventId::from_opaque(oid("snapshot-remove-caller")),\n                    scope: scope(),\n                    group_id: group.group_id.clone(),\n                    expected_revision: 2,\n                    kind: GroupChangeKind::RemoveMember {\n                        member: caller.principal.clone(),\n                    },\n                    next_crypto_state: None,\n                },\n            )\n            .expect("remove caller");\n        assert_eq!(\n            store.group_membership_for_active_member(\n                &caller,\n                &scope(),\n                &group.group_id,\n                &target.principal,\n            ),\n            Ok(None)\n        );\n        assert_eq!(\n            store.group_memberships_for_active_member(&caller, &scope(), &group.group_id, 16),\n            Err(DurableStoreError::PermissionDenied)\n        );\n    }\n\n'''
replace_once(
    "crates/ucr-storage-memory/src/group_store.rs",
    '''    #[test]\n    fn principal_kind_alias_cannot_inherit_group_membership() {\n''',
    memory_test + '''    #[test]\n    fn principal_kind_alias_cannot_inherit_group_membership() {\n'''
)

# SQLite implementation: caller check and returned data are inside one read transaction/snapshot.
replace_once(
    "crates/ucr-storage-sqlite/src/group_store.rs",
    '''    fn apply_group_change(\n        &self,\n        actor: &ScopedPrincipal,\n        change: &GroupChange,\n    ) -> Result<DurableRecordStatus, DurableStoreError> {\n''',
    '''    fn group_membership_for_active_member(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        member: &PrincipalRef,\n    ) -> Result<Option<GroupMembership>, DurableStoreError> {\n        if subject.scope != *scope {\n            return Err(DurableStoreError::PermissionDenied);\n        }\n        let mut connection = self.lock_connection()?;\n        let transaction = connection\n            .transaction()\n            .map_err(|error| map_sqlite_error(&error))?;\n        let caller = load_membership_from(\n            &transaction,\n            scope,\n            group_id,\n            &subject.principal,\n        )?;\n        if !caller.is_some_and(|membership| membership.state == GroupMemberState::Active) {\n            return Ok(None);\n        }\n        let result = load_membership_from(&transaction, scope, group_id, member)?;\n        transaction\n            .commit()\n            .map_err(|error| map_sqlite_error(&error))?;\n        Ok(result)\n    }\n\n    fn group_memberships_for_active_member(\n        &self,\n        subject: &ScopedPrincipal,\n        scope: &TenantScope,\n        group_id: &GroupId,\n        max_items: usize,\n    ) -> Result<Vec<GroupMembership>, DurableStoreError> {\n        if subject.scope != *scope {\n            return Err(DurableStoreError::PermissionDenied);\n        }\n        let mut connection = self.lock_connection()?;\n        let transaction = connection\n            .transaction()\n            .map_err(|error| map_sqlite_error(&error))?;\n        let caller = load_membership_from(\n            &transaction,\n            scope,\n            group_id,\n            &subject.principal,\n        )?;\n        if !caller.is_some_and(|membership| membership.state == GroupMemberState::Active) {\n            return Err(DurableStoreError::PermissionDenied);\n        }\n        validate_group_member_list_limit(max_items).map_err(map_group_error)?;\n        let group = load_group_from(&transaction, scope, group_id)?\n            .ok_or(DurableStoreError::InvalidRecord)?;\n        let result = load_memberships_from(&transaction, &group, max_items)?;\n        transaction\n            .commit()\n            .map_err(|error| map_sqlite_error(&error))?;\n        Ok(result)\n    }\n\n    fn apply_group_change(\n        &self,\n        actor: &ScopedPrincipal,\n        change: &GroupChange,\n    ) -> Result<DurableRecordStatus, DurableStoreError> {\n'''
)

sqlite_test = '''    #[test]\n    fn membership_gated_reads_fail_after_caller_removal() {\n        let db = TestDb::new();\n        let (conversation, group, owner) = group_fixture();\n        let caller = subject("phase18-snapshot-caller");\n        let target = ScopedPrincipal {\n            scope: scope(),\n            principal: PrincipalRef {\n                principal_id: PrincipalId::from_opaque(oid("phase18-snapshot-target")),\n                kind: PrincipalKind::Organization,\n            },\n        };\n        let store = SqliteLocalStore::open(db.path()).expect("open");\n        store.create_group(&conversation, &group, &owner).expect("group");\n        for (revision, event_id, principal) in [\n            (0, "phase18-snapshot-add-caller", caller.principal.clone()),\n            (1, "phase18-snapshot-add-target", target.principal.clone()),\n        ] {\n            store\n                .apply_group_change(\n                    &owner,\n                    &GroupChange {\n                        event_id: EventId::from_opaque(oid(event_id)),\n                        scope: scope(),\n                        group_id: group.group_id.clone(),\n                        expected_revision: revision,\n                        kind: GroupChangeKind::AddMember {\n                            member: principal,\n                            role: GroupRole::Member,\n                        },\n                        next_crypto_state: None,\n                    },\n                )\n                .expect("add member");\n        }\n        assert_eq!(\n            store\n                .group_membership_for_active_member(\n                    &caller,\n                    &scope(),\n                    &group.group_id,\n                    &target.principal,\n                )\n                .expect("gated membership")\n                .map(|membership| membership.member),\n            Some(target.principal.clone())\n        );\n        assert!(\n            store\n                .group_memberships_for_active_member(&caller, &scope(), &group.group_id, 16)\n                .expect("gated memberships")\n                .iter()\n                .any(|membership| membership.member == target.principal)\n        );\n        store\n            .apply_group_change(\n                &owner,\n                &GroupChange {\n                    event_id: EventId::from_opaque(oid("phase18-snapshot-remove-caller")),\n                    scope: scope(),\n                    group_id: group.group_id.clone(),\n                    expected_revision: 2,\n                    kind: GroupChangeKind::RemoveMember {\n                        member: caller.principal.clone(),\n                    },\n                    next_crypto_state: None,\n                },\n            )\n            .expect("remove caller");\n        assert_eq!(\n            store.group_membership_for_active_member(\n                &caller,\n                &scope(),\n                &group.group_id,\n                &target.principal,\n            ),\n            Ok(None)\n        );\n        assert_eq!(\n            store.group_memberships_for_active_member(&caller, &scope(), &group.group_id, 16),\n            Err(DurableStoreError::PermissionDenied)\n        );\n    }\n\n'''
